// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/
// https://twitter.com/KaufmanRoni

let margin = 60, u = 20;
let idCount = 0;
let arcs = [];

function setup() {
  createCanvas(24 * u + 2 * margin, 24 * u + 2 * margin);
  strokeWeight(5);
  noFill();
  // noLoop() removed for animation
}

function draw() {
  background("#0a0a0a");

  let divPossibilities = [1];
  let _wG_1 = 0; while ((divPossibilities.length == 1) && ++_wG_1 < 20000) {
    for (let d of [2, 3, 4, 6]) {
      if (random() < 1/2) divPossibilities.push(d);
    }
  }

  let y = margin, s;
  let _wG_2 = 0; while ((y < height - margin) && ++_wG_2 < 20000) {
    do {
      s = random(divPossibilities) * u;
    } while (y + s > height - margin);
    for (let x = margin; x < width - margin - 0.1; x += (Math.max(0.001, Math.abs(s)) || 1)) {
      makeTile(x, y, s);
    }
    y += s;
  }

  for (let x = margin; x < width - margin - u / 2; x += (Math.max(0.001, Math.abs(2 * u)) || 1)) {
    addArc(x + u, margin, u, PI, PI * 2);
    addArc(x + u, height - margin, u, 0, PI);
  }
  for (let y = margin; y < height - margin - u / 2; y += (Math.max(0.001, Math.abs(2 * u)) || 1)) {
    addArc(margin, y + u, u, PI / 2, (3 * PI) / 2);
    addArc(width - margin, y + u, u, (3 * PI) / 2, (5 * PI) / 2);
  }

  let ids = new Array(arcs.length).fill(0);
  stroke("#f5f5f5");
  for (let a of arcs) {
    arc(a.x, a.y, a.d, a.d, a.theta1, a.theta2);
    ids[a.id]++;
  }

  id = ids.indexOf(max([...ids]));
  stroke(random(["#0872db", "#f5d216", "#f43809"]));
  for (let a of arcs) {
    if (a.id == id) arc(a.x, a.y, a.d, a.d, a.theta1, a.theta2);
  }
}

function makeTile(x, y, s) {
  let dMin = s == u ? 0 : s == 2 * u ? 1 : s == 3 * u ? 2 : s == 4 * u ? 2 : 3;
  let dMax = s == u ? 1 : s == 2 * u ? 2 : s == 3 * u ? 3 : s == 4 * u ? 4 : 8;
  let d1 = floor(random(dMin, dMax + 1));
  let d2 = (2 * s) / u - d1 - 1;
  for (let i = 1; i <= d1; i++) {
    addArc(x, y, i * u, 0, PI / 2);
    addArc(x + s, y + s, i * u, PI, (3 * PI) / 2);
  }
  for (let i = 1; i <= d2; i++) {
    addArc(x + s, y, i * u, PI / 2, PI);
    addArc(x, y + s, i * u, (3 * PI) / 2, 2 * PI);
  }
}

function addArc(x, y, d, theta1, theta2) {
  let eps = 1;
  let id = -1;
  let x1 = x + (d / 2) * cos(theta1);
  let y1 = y + (d / 2) * sin(theta1);
  let x2 = x + (d / 2) * cos(theta2);
  let y2 = y + (d / 2) * sin(theta2);
  let matches = [];
  for (let a of arcs) {
    let a_x1 = a.x + (a.d / 2) * cos(a.theta1);
    let a_y1 = a.y + (a.d / 2) * sin(a.theta1);
    let a_x2 = a.x + (a.d / 2) * cos(a.theta2);
    let a_y2 = a.y + (a.d / 2) * sin(a.theta2);
    if (
      (abs(x1 - a_x1) < eps && abs(y1 - a_y1) < eps) ||
      (abs(x1 - a_x2) < eps && abs(y1 - a_y2) < eps) ||
      (abs(x2 - a_x1) < eps && abs(y2 - a_y1) < eps) ||
      (abs(x2 - a_x2) < eps && abs(y2 - a_y2) < eps)
    ) {
      matches.push(a.id);
    }
  }
  if (matches.length > 0) {
    id = matches[0];
    if (matches.length == 2) {
      for (let a of arcs) {
        if (a.id == matches[1]) a.id = matches[0];
      }
    }
  } else {
    id = idCount++;
  }
  arcs.push({
    x: x,
    y: y,
    d: d,
    theta1: theta1,
    theta2: theta2,
    id: id,
  });
}
